package com.rork.rockscout.data

import androidx.compose.ui.graphics.Color

/** Category tag for a glossary entry, with an associated accent color. */
enum class GlossaryCategory(val label: String, val accent: Color) {
    MINERALOGY("Mineralogy", Color(0xFF5CC9E6)),
    AURORA_SPACE("Aurora & Space", Color(0xFF5CC98C)),
    WEATHER("Weather", Color(0xFFFF8A3D)),
    PALEONTOLOGY("Paleontology", Color(0xFFE8C44A)),
    LAPIDARY("Lapidary", Color(0xFFE8A33D)),
    GEOLOGY("Geology", Color(0xFF6FA8C7)),
}

/** A single glossary entry: the term, its category, and a plain-language definition. */
data class GlossaryEntry(
    val term: String,
    val category: GlossaryCategory,
    val definition: String,
)

/** The full glossary, sorted alphabetically by term. */
val GLOSSARY_ENTRIES: List<GlossaryEntry> = listOf(
    // ── Mineralogy ────────────────────────────────────────────────────────
    GlossaryEntry("Adamantine luster", GlossaryCategory.MINERALOGY, "A brilliant, diamond-like shine — the brightest mineral luster. Diamond and cerussite show it."),
    GlossaryEntry("Adularescence", GlossaryCategory.MINERALOGY, "A soft, billowy blue or white glow that floats across a stone as you turn it. Moonstone is the classic example."),
    GlossaryEntry("Botryoidal", GlossaryCategory.MINERALOGY, "A surface shaped like a bunch of grapes — rounded, bubbly mounds. Common in hematite, malachite, and goethite."),
    GlossaryEntry("Birefringence", GlossaryCategory.MINERALOGY, "When a crystal splits light into two rays, making a double image through it. Calcite shows this strongly."),
    GlossaryEntry("Chatoyancy", GlossaryCategory.MINERALOGY, "The 'cat's eye' effect — a single bright band of light that slides across a stone as it's turned. Tiger's eye is the best known."),
    GlossaryEntry("Cleavage", GlossaryCategory.MINERALOGY, "A mineral's tendency to break along flat, smooth planes where the atomic bonds are weak. Mica cleaves into thin sheets."),
    GlossaryEntry("Crystal habit", GlossaryCategory.MINERALOGY, "The typical shape a mineral grows in — prismatic, bladed, tabular, acicular (needle-like), and so on."),
    GlossaryEntry("Druzy", GlossaryCategory.MINERALOGY, "A coating of tiny, sparkling crystals covering a surface or lining a cavity. Often seen on quartz geodes."),
    GlossaryEntry("Euhedral", GlossaryCategory.MINERALOGY, "A crystal with well-formed, visible faces — it had room to grow into its ideal shape."),
    GlossaryEntry("Fracture", GlossaryCategory.MINERALOGY, "The way a mineral breaks when it doesn't follow cleavage planes. Quartz shows a conchoidal (curved, shell-like) fracture."),
    GlossaryEntry("Geode", GlossaryCategory.MINERALOGY, "A hollow rock lined with crystals inside — usually quartz or calcite. Cut open to reveal the sparkling cavity."),
    GlossaryEntry("Hardness", GlossaryCategory.MINERALOGY, "A mineral's resistance to scratching. Measured on the Mohs scale from 1 (talc) to 10 (diamond)."),
    GlossaryEntry("Inclusion", GlossaryCategory.MINERALOGY, "A foreign material trapped inside a crystal as it grew — another mineral, a gas bubble, or water. Often visible in quartz and emerald."),
    GlossaryEntry("Iridescence", GlossaryCategory.MINERALOGY, "A rainbow play of color caused by light bending through thin layers. Seen in bornite ('peacock ore') and opal."),
    GlossaryEntry("Luster", GlossaryCategory.MINERALOGY, "How a mineral's surface reflects light — vitreous (glassy), metallic, adamantine, pearly, silky, or earthy."),
    GlossaryEntry("Massive", GlossaryCategory.MINERALOGY, "A mineral habit with no visible crystal shape — a compact, shapeless mass."),
    GlossaryEntry("Mohs scale", GlossaryCategory.MINERALOGY, "A 1–10 scratch-test scale of mineral hardness: 1 talc, 2 gypsum, 3 calcite, 4 fluorite, 5 apatite, 6 orthoclase, 7 quartz, 8 topaz, 9 corundum, 10 diamond."),
    GlossaryEntry("Nodule", GlossaryCategory.MINERALOGY, "A rounded, lumpy mass of mineral — smaller and more irregular than a geode, often solid throughout."),
    GlossaryEntry("Pearly luster", GlossaryCategory.MINERALOGY, "A soft, pearl-like sheen on a surface. Talc and muscovite mica can show it."),
    GlossaryEntry("Pegmatite", GlossaryCategory.MINERALOGY, "An extremely coarse-grained igneous rock, often the last bit of magma to crystallize. Produces large crystals of tourmaline, beryl, and feldspar."),
    GlossaryEntry("Phosphorescence", GlossaryCategory.MINERALOGY, "A glow that continues after the UV light is turned off — the mineral keeps releasing stored light energy."),
    GlossaryEntry("Play-of-color", GlossaryCategory.MINERALOGY, "Opal's signature flashing rainbow effect, caused by light diffraction through microscopic silica spheres."),
    GlossaryEntry("Pleochroism", GlossaryCategory.MINERALOGY, "When a crystal shows different colors when viewed from different angles. Tourmaline and tanzanite are strongly pleochroic."),
    GlossaryEntry("Pseudomorph", GlossaryCategory.MINERALOGY, "A mineral that has replaced another mineral's crystal shape while keeping the original form. 'False form.'"),
    GlossaryEntry("Silky luster", GlossaryCategory.MINERALOGY, "A fibrous, silk-like sheen — seen in fibrous gypsum (satin spar) and some asbestos minerals."),
    GlossaryEntry("Specific gravity", GlossaryCategory.MINERALOGY, "A measure of a mineral's density compared to water. Galena feels very heavy; quartz feels 'normal.'"),
    GlossaryEntry("Streak", GlossaryCategory.MINERALOGY, "The color of a mineral's powder when scraped on an unglazed porcelain plate. Often more reliable than the mineral's surface color."),
    GlossaryEntry("Tenacity", GlossaryCategory.MINERALOGY, "How a mineral resists bending or breaking — brittle, malleable, sectile (can be cut with a knife), or elastic."),
    GlossaryEntry("Tenebrescence", GlossaryCategory.MINERALOGY, "A reversible color change caused by light — hackmanite fades in sunlight and returns in the dark."),
    GlossaryEntry("Triboluminescence", GlossaryCategory.MINERALOGY, "A flash of light produced when a mineral is scratched, crushed, or rubbed. Some quartz and fluorite specimens show it."),
    GlossaryEntry("Thermoluminescence", GlossaryCategory.MINERALOGY, "A glow produced when a mineral is gently heated. Some fluorite specimens emit light when warmed."),
    GlossaryEntry("UV (SW / MW / LW)", GlossaryCategory.MINERALOGY, "Ultraviolet light bands used to make minerals fluoresce: Shortwave (254 nm), Midwave (312 nm), and Longwave (365 nm). Different minerals respond to different bands."),
    GlossaryEntry("Vitreous luster", GlossaryCategory.MINERALOGY, "A glass-like shine — the most common mineral luster. Quartz, fluorite, and olivine all show it."),
    GlossaryEntry("Vein", GlossaryCategory.MINERALOGY, "A sheet-like deposit of minerals filling a crack in rock. Quartz and calcite veins are common."),
    GlossaryEntry("Fluorescence", GlossaryCategory.MINERALOGY, "A glow produced when UV light hits a mineral and it emits visible light instantly. Stops when the UV is removed."),
    GlossaryEntry("Activator", GlossaryCategory.MINERALOGY, "The trace impurity (often manganese, lead, or a rare-earth element) that causes a mineral to fluoresce under UV."),
    GlossaryEntry("Anhedral", GlossaryCategory.MINERALOGY, "A crystal with no visible faces — it grew crowded against other minerals and couldn't form its ideal shape."),
    GlossaryEntry("Subhedral", GlossaryCategory.MINERALOGY, "A crystal with partial, imperfect faces — somewhere between euhedral (perfect) and anhedral (no faces)."),

    // ── Aurora & Space ────────────────────────────────────────────────────
    GlossaryEntry("Bz", GlossaryCategory.AURORA_SPACE, "The north–south component of the interplanetary magnetic field. When Bz points south (negative), it connects with Earth's field and lets solar energy in — triggering aurora."),
    GlossaryEntry("CME (Coronal Mass Ejection)", GlossaryCategory.AURORA_SPACE, "A massive burst of solar plasma and magnetic field hurled from the Sun. When one hits Earth, it can trigger a geomagnetic storm and widespread aurora."),
    GlossaryEntry("Coronal hole", GlossaryCategory.AURORA_SPACE, "A dark patch on the Sun where the magnetic field opens into space, letting high-speed solar wind escape. A common, steady source of aurora activity."),
    GlossaryEntry("F10.7", GlossaryCategory.AURORA_SPACE, "A measure of solar radio flux at 10.7-centimeter wavelength — a proxy for overall solar activity. Higher values mean more energy available for aurora."),
    GlossaryEntry("Flare class (A/B/C/M/X)", GlossaryCategory.AURORA_SPACE, "Solar flare strength categories, weakest to strongest: A, B, C, M, X. Each class is 10× the one before it. M and X flares can drive major aurora."),
    GlossaryEntry("Geomagnetic storm (G1–G5)", GlossaryCategory.AURORA_SPACE, "NOAA's 5-level storm scale: G1 minor, G2 moderate, G3 strong, G4 severe, G5 extreme. Higher levels push the aurora oval farther south."),
    GlossaryEntry("Ionosphere", GlossaryCategory.AURORA_SPACE, "The upper layer of Earth's atmosphere where solar particles excite atoms and create the glowing aurora."),
    GlossaryEntry("Kp index", GlossaryCategory.AURORA_SPACE, "A 0–9 scale of geomagnetic disturbance, measured every 3 hours. Kp 5+ means a geomagnetic storm; higher Kp pushes the aurora visible farther south."),
    GlossaryEntry("Magnetosphere", GlossaryCategory.AURORA_SPACE, "The magnetic bubble around Earth that deflects most of the solar wind. Aurora forms where some particles sneak in near the poles."),
    GlossaryEntry("Solar flare", GlossaryCategory.AURORA_SPACE, "A sudden, intense flash of light and radiation from the Sun. The biggest flares can trigger aurora a day or two later."),
    GlossaryEntry("Solar wind", GlossaryCategory.AURORA_SPACE, "A constant stream of charged particles flowing from the Sun. Faster, denser wind means stronger aurora."),
    GlossaryEntry("Substorm", GlossaryCategory.AURORA_SPACE, "A sudden, explosive brightening and expansion of the aurora — often the most vivid, dancing displays happen during a substorm."),
    GlossaryEntry("Aurora oval", GlossaryCategory.AURORA_SPACE, "The ring-shaped zone around each magnetic pole where aurora most commonly appears. It expands equatorward during storms."),
    GlossaryEntry("IMF (Interplanetary Magnetic Field)", GlossaryCategory.AURORA_SPACE, "The Sun's magnetic field carried through space by the solar wind. Its orientation (especially the Bz component) controls whether aurora fires."),
    GlossaryEntry("NOAA", GlossaryCategory.AURORA_SPACE, "The U.S. National Oceanic and Atmospheric Administration — operates the SWPC space-weather monitoring center."),
    GlossaryEntry("SWPC", GlossaryCategory.AURORA_SPACE, "NOAA's Space Weather Prediction Center — the source of the Kp forecasts, watches, and warnings this app uses."),
    GlossaryEntry("Visibility threshold", GlossaryCategory.AURORA_SPACE, "The minimum Kp needed to see aurora from your latitude. Higher (farther south) latitudes need higher Kp."),

    // ── Weather ───────────────────────────────────────────────────────────
    GlossaryEntry("Advisory", GlossaryCategory.WEATHER, "A NWS alert for conditions that are inconvenient or hazardous but not immediately life-threatening."),
    GlossaryEntry("Air quality", GlossaryCategory.WEATHER, "A measure of pollutants in the air, often reported as an AQI index. Smoke from wildfires can make it dangerous to be outdoors."),
    GlossaryEntry("Bow echo", GlossaryCategory.WEATHER, "A bow-shaped radar signature of a line of damaging thunderstorms. Often produces straight-line winds and occasional tornadoes."),
    GlossaryEntry("CAPE", GlossaryCategory.WEATHER, "Convective Available Potential Energy — a measure of fuel for thunderstorms. Higher CAPE means stronger updrafts and bigger storms."),
    GlossaryEntry("Convective", GlossaryCategory.WEATHER, "Relating to rising warm air and sinking cool air — the engine that drives thunderstorms."),
    GlossaryEntry("Dense smoke advisory", GlossaryCategory.WEATHER, "A NWS alert issued when wildfire smoke reduces visibility enough to make travel hazardous."),
    GlossaryEntry("Derecho", GlossaryCategory.WEATHER, "A widespread, long-lived wind storm caused by a fast-moving line of thunderstorms. Produces damage along a path hundreds of miles long."),
    GlossaryEntry("Flash flood", GlossaryCategory.WEATHER, "A sudden, dangerous flood — usually within a few hours of heavy rain. Can sweep away vehicles and fill slot canyons."),
    GlossaryEntry("Helicity", GlossaryCategory.WEATHER, "A measure of spin in the lower atmosphere. High helicity plus high CAPE means a tornado risk."),
    GlossaryEntry("Hook echo", GlossaryCategory.WEATHER, "A hook-shaped radar signature that often marks a tornado-producing supercell."),
    GlossaryEntry("Mesocyclone", GlossaryCategory.WEATHER, "The rotating updraft inside a supercell thunderstorm — the precursor to most tornadoes."),
    GlossaryEntry("NWS", GlossaryCategory.WEATHER, "The U.S. National Weather Service — issues watches, warnings, and advisories."),
    GlossaryEntry("Red flag warning", GlossaryCategory.WEATHER, "A NWS alert for critical fire weather — hot, dry, windy conditions where any spark can explode into a wildfire."),
    GlossaryEntry("RFD (Rear Flank Downdraft)", GlossaryCategory.WEATHER, "A rush of cold, dry air on the back side of a supercell. Often wraps around the tornado."),
    GlossaryEntry("Shear", GlossaryCategory.WEATHER, "Wind that changes speed or direction with height. Strong shear tilts storms and helps them rotate."),
    GlossaryEntry("Squall line", GlossaryCategory.WEATHER, "A solid line of thunderstorms out ahead of a cold front. Often produces damaging winds and hail."),
    GlossaryEntry("SPC (Storm Prediction Center)", GlossaryCategory.WEATHER, "The NOAA center that issues severe thunderstorm and tornado outlooks and watches."),
    GlossaryEntry("Supercell", GlossaryCategory.WEATHER, "The most powerful thunderstorm type — a long-lived storm with a rotating updraft. Produces the largest hail and strongest tornadoes."),
    GlossaryEntry("Severe thunderstorm", GlossaryCategory.WEATHER, "A thunderstorm with winds ≥58 mph, hail ≥1 inch, or a tornado. Triggers a NWS warning."),
    GlossaryEntry("Tornado", GlossaryCategory.WEATHER, "A violently rotating column of air touching the ground. The most intense weather phenomenon on Earth."),
    GlossaryEntry("Wall cloud", GlossaryCategory.WEATHER, "A lowered, rotating cloud base beneath a supercell — often where a tornado forms."),
    GlossaryEntry("Watch", GlossaryCategory.WEATHER, "A NWS alert meaning conditions are favorable for severe weather in the next few hours. Stay alert."),
    GlossaryEntry("Warning", GlossaryCategory.WEATHER, "A NWS alert meaning severe weather is occurring or imminent. Take action now."),

    // ── Paleontology ──────────────────────────────────────────────────────
    GlossaryEntry("Ammonite", GlossaryCategory.PALEONTOLOGY, "An extinct, coiled-shell marine animal related to squid. Their fossils are common and often iridescent."),
    GlossaryEntry("Cast / mold", GlossaryCategory.PALEONTOLOGY, "A cast is a copy of a fossil formed when sediment fills a mold (the hollow left when the original dissolved)."),
    GlossaryEntry("Cenozoic", GlossaryCategory.PALEONTOLOGY, "The current geologic era — from 66 million years ago to today. The 'age of mammals.'"),
    GlossaryEntry("Epoch", GlossaryCategory.PALEONTOLOGY, "A subdivision of a geologic period. Example: the Pleistocene epoch is part of the Quaternary period."),
    GlossaryEntry("Era", GlossaryCategory.PALEONTOLOGY, "The largest division of geologic time. The three eras of the Phanerozoic are Paleozoic, Mesozoic, and Cenozoic."),
    GlossaryEntry("Eurypterid", GlossaryCategory.PALEONTOLOGY, "An extinct 'sea scorpion' — giant arthropods that lived in ancient oceans. New York's state fossil."),
    GlossaryEntry("Fossil", GlossaryCategory.PALEONTOLOGY, "Any preserved trace of ancient life — a bone, shell, footprint, or impression — at least 10,000 years old."),
    GlossaryEntry("Gondwana", GlossaryCategory.PALEONTOLOGY, "An ancient southern supercontinent that included Africa, South America, India, Antarctica, and Australia."),
    GlossaryEntry("Graptolite", GlossaryCategory.PALEONTOLOGY, "Tiny extinct colonial animals that floated ancient oceans. Their fossils look like saw-blade or pencil marks on rock."),
    GlossaryEntry("Index fossil", GlossaryCategory.PALEONTOLOGY, "A fossil from a species that lived briefly but widely — used to date the rock layer it's found in."),
    GlossaryEntry("Lagerstätte", GlossaryCategory.PALEONTOLOGY, "A rare fossil site with exceptional preservation — soft tissues, feathers, or complete skeletons. 'Storage place' in German."),
    GlossaryEntry("Mass extinction", GlossaryCategory.PALEONTOLOGY, "A event where a large percentage of species die out in a short time. The 'Big Five' mass extinctions shaped life on Earth."),
    GlossaryEntry("Mesozoic", GlossaryCategory.PALEONTOLOGY, "The era from 252 to 66 million years ago — the 'age of reptiles.' Includes Triassic, Jurassic, and Cretaceous periods."),
    GlossaryEntry("Orthoceras", GlossaryCategory.PALEONTOLOGY, "An extinct straight-shelled nautiloid. Fossils are common in Moroccan limestone and often sold polished."),
    GlossaryEntry("Paleozoic", GlossaryCategory.PALEONTOLOGY, "The era from 541 to 252 million years ago — the 'age of ancient life.' Includes Cambrian, Ordovician, and others."),
    GlossaryEntry("Pangaea", GlossaryCategory.PALEONTOLOGY, "The supercontinent that existed from about 335 to 175 million years ago. All major landmasses were joined together."),
    GlossaryEntry("Period", GlossaryCategory.PALEONTOLOGY, "A subdivision of an era. Example: the Jurassic is a period of the Mesozoic era."),
    GlossaryEntry("Permineralization", GlossaryCategory.PALEONTOLOGY, "Fossilization where mineral-rich water fills the pores of a bone or wood, turning it to stone over time."),
    GlossaryEntry("Precambrian", GlossaryCategory.PALEONTOLOGY, "All geologic time before the Cambrian (before 541 million years ago) — most of Earth's history."),
    GlossaryEntry("Preservation", GlossaryCategory.PALEONTOLOGY, "The process by which an organism becomes a fossil — usually requires rapid burial and mineral replacement."),
    GlossaryEntry("Replacement", GlossaryCategory.PALEONTOLOGY, "Fossilization where the original material is slowly swapped for a mineral (often silica or pyrite), molecule by molecule."),
    GlossaryEntry("Trace fossil", GlossaryCategory.PALEONTOLOGY, "Evidence of an animal's activity rather than the animal itself — tracks, burrows, or coprolites (fossil dung)."),
    GlossaryEntry("Trilobite", GlossaryCategory.PALEONTOLOGY, "An extinct marine arthropod with a three-lobed body. One of the most iconic and collectible fossils."),

    // ── Lapidary ──────────────────────────────────────────────────────────
    GlossaryEntry("Cabochon", GlossaryCategory.LAPIDARY, "A gemstone cut with a smooth, rounded top and flat bottom — no facets. 'Cab' for short. Best for opaque or chatoyant stones."),
    GlossaryEntry("Carat", GlossaryCategory.LAPIDARY, "A unit of gem weight: 1 carat = 0.2 grams. Abbreviated 'ct.'"),
    GlossaryEntry("Cerium oxide", GlossaryCategory.LAPIDARY, "A pale yellow polish compound used for the final mirror finish on quartz, glass, and agate."),
    GlossaryEntry("Cut", GlossaryCategory.LAPIDARY, "The shape and quality of a finished gem — faceted or cabochon. 'Cut' also means the work of shaping a stone."),
    GlossaryEntry("Dop wax", GlossaryCategory.LAPIDARY, "A sticky wax used to attach a gem to a 'dop stick' (a handle) so it can be held during faceting."),
    GlossaryEntry("Dopping", GlossaryCategory.LAPIDARY, "The act of attaching a stone to a dop stick with dop wax so it can be precisely oriented for cutting and polishing."),
    GlossaryEntry("Faceting", GlossaryCategory.LAPIDARY, "Cutting a transparent gem with many flat, angled faces (facets) to maximize brilliance and fire."),
    GlossaryEntry("Grit", GlossaryCategory.LAPIDARY, "The abrasive powder (silicon carbide, diamond) used on grinding wheels. Measured in mesh — smaller numbers are coarser."),
    GlossaryEntry("Polish", GlossaryCategory.LAPIDARY, "The final, mirror-smooth stage of finishing a gem — done with a very fine compound on a soft pad."),
    GlossaryEntry("Polish compound", GlossaryCategory.LAPIDARY, "A fine abrasive paste used for the final finish: aluminum oxide (general), cerium oxide (quartz/glass), tin oxide (some stones)."),
    GlossaryEntry("Preform", GlossaryCategory.LAPIDARY, "The rough-shaped stone before final cutting — the stage between slab and finished cab."),
    GlossaryEntry("Rough", GlossaryCategory.LAPIDARY, "Unworked, uncut gemstone material as it comes from the ground — the starting point for cutting."),
    GlossaryEntry("Slab", GlossaryCategory.LAPIDARY, "A thin slice cut from a rough rock on a trim saw — the first step in making a cabochon."),
    GlossaryEntry("Template", GlossaryCategory.LAPIDARY, "A metal or plastic outline guide used to mark the shape of a cabochon on a slab before cutting."),
    GlossaryEntry("Tumbling", GlossaryCategory.LAPIDARY, "Polishing rocks in a rotating barrel with progressively finer grits over weeks. Produces smooth, polished pebbles."),

    // ── Geology ───────────────────────────────────────────────────────────
    GlossaryEntry("Basalt", GlossaryCategory.GEOLOGY, "A dark, fine-grained volcanic rock — the most common volcanic rock on Earth. Forms much of the ocean floor."),
    GlossaryEntry("Breccia", GlossaryCategory.GEOLOGY, "A sedimentary rock made of angular, broken fragments cemented together — formed by landslides, impacts, or faulting."),
    GlossaryEntry("Conglomerate", GlossaryCategory.GEOLOGY, "A sedimentary rock made of rounded pebbles cemented in a finer matrix — an ancient riverbed or beach gravel turned to stone."),
    GlossaryEntry("Erosion", GlossaryCategory.GEOLOGY, "The removal and transport of rock and soil by water, wind, ice, or gravity. Sculpt the land surface over time."),
    GlossaryEntry("Fault", GlossaryCategory.GEOLOGY, "A crack in the Earth's crust where rocks have slipped past each other. Earthquakes happen on faults."),
    GlossaryEntry("Granite", GlossaryCategory.GEOLOGY, "A coarse, light-colored igneous rock rich in quartz and feldspar. Common in continental crust."),
    GlossaryEntry("Hydrothermal", GlossaryCategory.GEOLOGY, "Relating to hot, mineral-rich water — the source of many ore deposits and crystal pockets. 'Hot water.'"),
    GlossaryEntry("Igneous", GlossaryCategory.GEOLOGY, "Rock formed from the cooling and solidifying of magma or lava. Basalt and granite are igneous."),
    GlossaryEntry("Limestone", GlossaryCategory.GEOLOGY, "A sedimentary rock made mostly of calcium carbonate — often from accumulated shells and coral. Caves form in it."),
    GlossaryEntry("Magma", GlossaryCategory.GEOLOGY, "Molten rock below the Earth's surface. When it erupts, it becomes lava."),
    GlossaryEntry("Lava", GlossaryCategory.GEOLOGY, "Molten rock once it reaches the surface — magma that has erupted from a volcano."),
    GlossaryEntry("Marble", GlossaryCategory.GEOLOGY, "A metamorphic rock formed from limestone under heat and pressure. Used for sculpture and building."),
    GlossaryEntry("Metamorphic", GlossaryCategory.GEOLOGY, "Rock changed by heat, pressure, or hot fluids — without fully melting. Marble (from limestone) and schist are metamorphic."),
    GlossaryEntry("Obsidian", GlossaryCategory.GEOLOGY, "A volcanic glass — lava cooled so fast no crystals formed. Breaks with sharp, conchoidal fractures."),
    GlossaryEntry("Ophiolite", GlossaryCategory.GEOLOGY, "A slice of oceanic crust and upper mantle thrust up onto land — a window into the deep Earth."),
    GlossaryEntry("Peridotite", GlossaryCategory.GEOLOGY, "A coarse, dark, ultra-mafic igneous rock of the mantle. The source rock of diamonds and peridot."),
    GlossaryEntry("Plate tectonics", GlossaryCategory.GEOLOGY, "The theory that Earth's crust is broken into moving plates. Their collisions build mountains and volcanoes."),
    GlossaryEntry("Pumice", GlossaryCategory.GEOLOGY, "A frothy volcanic rock so full of gas bubbles it floats on water. Used as an abrasive."),
    GlossaryEntry("Quartzite", GlossaryCategory.GEOLOGY, "A very hard metamorphic rock formed from sandstone. Doesn't scratch with a knife."),
    GlossaryEntry("Rock cycle", GlossaryCategory.GEOLOGY, "The endless loop where igneous, sedimentary, and metamorphic rocks transform into one another over geologic time."),
    GlossaryEntry("Sandstone", GlossaryCategory.GEOLOGY, "A sedimentary rock made of sand grains (mostly quartz) cemented together. Forms cliffs and canyons."),
    GlossaryEntry("Schist", GlossaryCategory.GEOLOGY, "A metamorphic rock with visible, aligned mica or chlorite flakes — gives it a sparkly, layered look."),
    GlossaryEntry("Scoria", GlossaryCategory.GEOLOGY, "A dark, vesicular volcanic rock — heavier than pumice and doesn't float."),
    GlossaryEntry("Sedimentary", GlossaryCategory.GEOLOGY, "Rock formed by the accumulation and cementing of sediment — sandstone, shale, limestone. Often holds fossils."),
    GlossaryEntry("Shale", GlossaryCategory.GEOLOGY, "A fine-grained sedimentary rock made of compacted mud or clay. Splits into thin layers."),
    GlossaryEntry("Shear zone", GlossaryCategory.GEOLOGY, "A band of rock deformed by intense, sideways-directed pressure. Often hosts gold and other hydrothermal deposits."),
    GlossaryEntry("Subduction", GlossaryCategory.GEOLOGY, "Where one tectonic plate dives beneath another into the mantle. Produces volcanoes and earthquakes."),
    GlossaryEntry("Tuff", GlossaryCategory.GEOLOGY, "A rock made of consolidated volcanic ash. Light, soft, and easy to cut — used as building stone since antiquity."),
    GlossaryEntry("Weathering", GlossaryCategory.GEOLOGY, "The breakdown of rock at or near Earth's surface — by water, ice, wind, chemicals, or living things."),

    // ── Expanded Mineralogy ───────────────────────────────────────────────
    GlossaryEntry("Acicular", GlossaryCategory.MINERALOGY, "Needle-like crystal habit — slender, pointed crystals. Tourmaline and rutile often grow this way."),
    GlossaryEntry("Amorphous", GlossaryCategory.MINERALOGY, "Lacking a regular crystal structure — no ordered atomic lattice. Opal and obsidian are amorphous."),
    GlossaryEntry("Conchoidal fracture", GlossaryCategory.MINERALOGY, "Smooth, curved break surfaces like the inside of a seashell. Quartz, obsidian, and glass all show it."),
    GlossaryEntry("Crystal system", GlossaryCategory.MINERALOGY, "One of 7 categories classifying crystals by symmetry: cubic, tetragonal, orthorhombic, monoclinic, triclinic, hexagonal, trigonal."),
    GlossaryEntry("Feldspar group", GlossaryCategory.MINERALOGY, "The most abundant mineral family in Earth's crust — plagioclase and orthoclase. Includes moonstone, labradorite, and amazonite."),
    GlossaryEntry("Gangue", GlossaryCategory.MINERALOGY, "The worthless minerals mixed in with valuable ore in a deposit — quartz and calcite are common gangue."),
    GlossaryEntry("Hackly fracture", GlossaryCategory.MINERALOGY, "A rough, jagged break with sharp edges — characteristic of native copper and silver."),
    GlossaryEntry("Mafic", GlossaryCategory.MINERALOGY, "Rich in magnesium and iron — describes dark igneous rocks like basalt and peridotite."),
    GlossaryEntry("Matrix", GlossaryCategory.MINERALOGY, "The host rock or surrounding material in which crystals or fossils are embedded."),
    GlossaryEntry("Octahedrite", GlossaryCategory.MINERALOGY, "An octahedral crystal habit — diamond and fluorite often crystallize as octahedrons."),
    GlossaryEntry("Vug", GlossaryCategory.MINERALOGY, "A small cavity in rock lined with crystals — essentially a miniature geode. Often found in volcanic basalts."),
    GlossaryEntry("Zeolite", GlossaryCategory.MINERALOGY, "A group of hydrated framework silicates that form in volcanic cavities. Includes stilbite, heulandite, and natrolite."),

    // ── Expanded Geology ──────────────────────────────────────────────────
    GlossaryEntry("Lithification", GlossaryCategory.GEOLOGY, "The process of turning loose sediment into solid rock — compaction, cementation, and hardening over time."),
    GlossaryEntry("Placer deposit", GlossaryCategory.GEOLOGY, "A concentration of heavy minerals (gold, garnet, magnetite) accumulated by water sorting in a stream or beach."),
    GlossaryEntry("Schistosity", GlossaryCategory.GEOLOGY, "The planar foliation in schist caused by aligned mica or chlorite flakes — gives the rock its characteristic layered look."),
    GlossaryEntry("Stratification", GlossaryCategory.GEOLOGY, "The layering of sedimentary rocks — each layer (stratum) represents a different episode of deposition."),
    GlossaryEntry("Unconformity", GlossaryCategory.GEOLOGY, "A gap in the geologic record where erosion removed layers before younger ones were deposited — a missing chapter in time."),
    GlossaryEntry("Vein (mineral)", GlossaryCategory.GEOLOGY, "A fracture filled with minerals deposited by hot water — quartz veins, gold veins, calcite veins."),
    GlossaryEntry("Xenolith", GlossaryCategory.GEOLOGY, "A fragment of older rock trapped inside igneous rock — a 'foreign stone' carried up by magma."),

    // ── Expanded Paleontology ─────────────────────────────────────────────
    GlossaryEntry("Coprolite", GlossaryCategory.PALEONTOLOGY, "Fossilized dung — yes, fossil poop. Contains clues about what ancient animals ate. Found worldwide."),
    GlossaryEntry("Petrified wood", GlossaryCategory.PALEONTOLOGY, "Wood replaced mineral by mineral (usually silica) so it's literally stone — but still shows every ring and grain."),

    // ── Expanded Lapidary ─────────────────────────────────────────────────
    GlossaryEntry("Cabochon (cab)", GlossaryCategory.LAPIDARY, "A gem cut with a smooth domed top and flat bottom — no facets. Best for opaque, chatoyant, or translucent stones."),
    GlossaryEntry("Diamond saw", GlossaryCategory.LAPIDARY, "A circular saw blade with diamond-impregnated edges used to slice rocks and slabs. The workhorse of any lapidary shop."),
    GlossaryEntry("Fire", GlossaryCategory.LAPIDARY, "The rainbow flashes of color in a faceted gem caused by dispersion — diamond and zircon show strong fire."),
    GlossaryEntry("Hardness tester", GlossaryCategory.LAPIDARY, "A set of known reference minerals or picks used to determine a stone's Mohs hardness by scratch testing."),

    // ── Expanded Aurora & Space ───────────────────────────────────────────
    GlossaryEntry("Proton flare", GlossaryCategory.AURORA_SPACE, "A powerful solar flare that accelerates protons toward Earth — can cause radio blackouts and enhanced aurora."),
    GlossaryEntry("Sudden impulse", GlossaryCategory.AURORA_SPACE, "A sharp, sudden jump in Earth's magnetic field when a solar shock front arrives — often precedes a geomagnetic storm."),

    // ── Expanded Weather ──────────────────────────────────────────────────
    GlossaryEntry("Advection fog", GlossaryCategory.WEATHER, "Fog formed when warm, moist air blows over a colder surface — common on coastlines and over cold ocean currents."),
    GlossaryEntry("Microburst", GlossaryCategory.WEATHER, "A small, intense downdraft from a thunderstorm that slams the ground and spreads outward — can cause damage like a tornado."),
    GlossaryEntry("Tornado alley", GlossaryCategory.WEATHER, "The central US region (TX, OK, KS, NE) where conditions produce more tornadoes than anywhere on Earth."),
).sortedBy { it.term.lowercase() }

/** All unique first letters present in the glossary, in A–Z order. */
val GLOSSARY_LETTERS: List<Char> = GLOSSARY_ENTRIES
    .map { it.term.first().uppercaseChar() }
    .distinct()
    .sorted()
